function validate([nums, divisors]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (divisors.length < 1 || divisors.length > 1000) return 'divisors needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each nums value is an integer from 1 to 10^9.';
  if (divisors.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each divisor is an integer from 1 to 10^9.';
  return null;
}

