function maxDivScore(nums, divisors) {
  let bestDivisor = divisors[0];
  let bestScore = -1;

  for (const divisor of divisors) {
    let score = 0;
    for (const num of nums) {
      if (num % divisor === 0) {
        score++;
      }
    }
    if (score > bestScore || (score === bestScore && divisor < bestDivisor)) {
      bestScore = score;
      bestDivisor = divisor;
    }
  }
  return bestDivisor;
}

