function maxDivScore(nums, divisors) {
  const scores = divisors.map(d => nums.filter(x => x % d === 0).length);
  const top = Math.max(...scores);
  const winners = divisors.filter((d, i) => scores[i] === top);
  return Math.min(...winners);
}

